// Раздел «Финансы»: интерфейс демо docs/crm-demo, данные — на сервере (/api/finance). Формулы — server/finance/ledger.js,
// тот же файл отдаётся браузеру (/finance-ledger.js), сервер перепроверяет каждое сохранение.
(()=>{'use strict';
const F=window.TAFinance;let root=null,state=null,meta={usage:[],empty:false};const $=s=>root.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let page='overview',period='',chartType='donut',chartMetric='expenses',search='',kindFilter='all',showDeleted=false,drill=null,editing=null,confirmAction=null;let scenario={sale:800000,purchase:560000,direct:40000,count:2,services:48000};
const money=n=>new Intl.NumberFormat('ru-RU',{minimumFractionDigits:n%100?2:0,maximumFractionDigits:n%100?2:0}).format(n/100)+' ₽';const pct=n=>new Intl.NumberFormat('ru-RU',{maximumFractionDigits:1}).format(n)+'%';const names={overview:'Обзор и графики',deals:'Тендерные сделки',operations:'Операции',services:'Подписки и серверы',partners:'Участники и вложения',budgets:'Бюджеты и план',accounts:'Счета',settings:'Настройки'};
const paths={overview:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',deals:'M3 7h18v14H3zM8 7V3h8v4M3 12h18',operations:'M4 5h16M4 12h16M4 19h16',services:'M4 3h16v7H4zM4 14h16v7H4zM7 6h.01M7 17h.01',partners:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8M18 8a3 3 0 0 1 0 6',budgets:'M3 21V3M3 21h18M7 16l5-7 4 3 5-7',accounts:'M3 6h18v14H3zM3 10h18M15 15h3',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M12 2v3M12 19v3M2 12h3M19 12h3M5 5l2 2M17 17l2 2M19 5l-2 2M7 17l-2 2',plus:'M12 5v14M5 12h14',arrow:'M5 12h14M14 7l5 5-5 5'};
const icon=(k,size=17)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[k]||paths.services}"/></svg>`;
const lookup=(g,id)=>state[g].find(x=>x.id===id),pname=id=>lookup('participants',id)?.name||'Проект';const shortDate=d=>new Date(d+'T12:00:00Z').toLocaleDateString('ru-RU',{day:'numeric',month:'short',timeZone:'UTC'});const monthName=m=>new Date(m+'-01T12:00:00Z').toLocaleDateString('ru-RU',{month:'long',year:'numeric',timeZone:'UTC'});const monthShort=m=>new Date(m+'-01T12:00:00Z').toLocaleDateString('ru-RU',{month:'short',timeZone:'UTC'});const currentMonth=()=>period==='all'?state.asOf.slice(0,7):period;
function bounds(m=period){if(m==='all')return['2000-01-01',state.asOf];const last=F.addMonth(m+'-01',1),end=new Date(Date.parse(last+'T00:00:00Z')-86400000).toISOString().slice(0,10);return[m+'-01',end<state.asOf?end:state.asOf];}
function months(){const end=currentMonth()+'-01';return Array.from({length:6},(_,i)=>F.addMonth(end,i-5).slice(0,7));}
function report(){return F.report(state,...bounds());}
async function api(path,body){const r=await fetch(path,body===undefined?undefined:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const j=await r.json().catch(()=>({}));if(!r.ok)throw Error(j.error||'Сервер не ответил. Попробуйте ещё раз.');return j;}
function apply(j,message){state=j.state;meta=j.meta||meta;render();if(message)toast(message);}
async function change(collection,id,patch,action,message){F.change(state,collection,id,patch,action);apply(await api('/api/finance/change',{collection,id,patch,action}),message);}
let toastTimer;function toast(t){$('#fin-toast').textContent=t;$('#fin-toast').classList.remove('hidden');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#fin-toast').classList.add('hidden'),6000);}
function uid(){return globalThis.crypto?.randomUUID?.()||'id-'+Date.now()+'-'+Math.random().toString(36).slice(2);}
function toolbar(){const dates=state.operations.map(o=>o.date.slice(0,7));dates.push(state.asOf.slice(0,7),...months());const unique=[...new Set(dates)].filter(m=>m<=state.asOf.slice(0,7)).sort().reverse();return`<div class="toolbar"><div class="monthstrip">${helpBtn('fin_period')}${months().map(m=>`<button data-month="${m}" class="${period===m?'active':''}">${monthShort(m)}</button>`).join('')}</div><label><span class="sr-only">Период отчёта</span><select class="select" id="fin-period">${unique.map(m=>`<option value="${m}" ${period===m?'selected':''}>${monthName(m)}${m===state.asOf.slice(0,7)?' · по '+Number(state.asOf.slice(-2)):''}</option>`).join('')}<option value="all" ${period==='all'?'selected':''}>За всё время</option></select></label></div>`;}
function head(title,sub,collection='operations',label='Операция'){return`<div class="pagehead"><div><div class="eyebrow">${esc(state.settings.name)} · тендерный бизнес</div><h1>${title} ${helpBtn('fin_'+page)}</h1><p class="subtitle">${sub}</p></div>${collection?`<button class="btn primary" data-new="${collection}">${icon('plus')} ${label}</button>`:''}</div>${toolbar()}`;}
function kpi(label,val,small,cls){return`<article class="kpi ${cls}"><div class="label">${label}</div><div class="value num ${val<0?'bad':cls==='result'?'blue':''}">${money(val)}</div><small>${small}</small></article>`;}
function actionButtons(collection,item){return item.deleted?`<button class="mini restore" data-restore="${collection}" data-id="${esc(item.id)}">Восстановить</button>`:`<button class="mini" data-edit="${collection}" data-id="${esc(item.id)}">Изменить</button> <button class="mini remove" data-delete="${collection}" data-id="${esc(item.id)}">Удалить</button>`;}
function archivedToggle(label='Показать удалённые'){return`<label class="archived-toggle"><input id="fin-showDeleted" type="checkbox" ${showDeleted?'checked':''}>${label}</label>${helpBtn('fin_archived')}`;}
function visibleItems(g){return state[g].filter(x=>showDeleted?x.deleted:!x.deleted);}
function chartRows(from,to){if(chartMetric==='expenses')return F.expenseRows(state,from,to);if(chartMetric==='capital')return state.participants.map(p=>({id:p.id,name:p.name,color:p.color,value:state.operations.filter(o=>!o.deleted&&o.kind==='capital'&&o.partnerId===p.id&&o.date>=from&&o.date<=to).reduce((s,o)=>s+o.amount,0)}));const r=F.report(state,from,to);return[{id:'sales',name:'Продажи',color:'#1b9b65',value:r.revenue},{id:'costs',name:'Все расходы',color:'#e34d60',value:r.cogs+r.direct+r.overhead},{id:'profit',name:'Результат до налогов',color:'#2878ed',value:r.result}];}
function donut(){const rows=chartRows(...bounds()).filter(x=>x.value>0),total=rows.reduce((s,x)=>s+x.value,0);if(!total)return'<div class="empty-chart">За выбранный период нет данных для круговой диаграммы.</div>';const circumference=2*Math.PI*94;let offset=0;const circles=rows.map(x=>{const size=x.value/total*circumference,html=`<circle cx="145" cy="145" r="94" fill="none" stroke="${esc(x.color)}" stroke-width="31" stroke-dasharray="${Math.max(0,size-3)} ${circumference-Math.max(0,size-3)}" stroke-dashoffset="${-offset}" transform="rotate(-90 145 145)"><title>${esc(x.name)}: ${money(x.value)} (${pct(x.value/total*100)})</title></circle>`;offset+=size;return html;}).join('');return`<div class="doughnut-layout"><svg class="doughnut" viewBox="0 0 290 290" role="img" aria-label="${chartMetric==='capital'?'Вложения участников':'Структура расходов'} за выбранный период"><circle cx="145" cy="145" r="94" fill="none" stroke="#edf0f4" stroke-width="31"/>${circles}<text x="145" y="139" text-anchor="middle" class="caption">${chartMetric==='capital'?'ВЛОЖЕНО В КАПИТАЛ':'ВСЕГО РАСХОДОВ'}</text><text x="145" y="169" text-anchor="middle" class="total">${money(total)}</text></svg><div class="chart-legend">${rows.sort((a,b)=>b.value-a.value).map(x=>`<button class="legend-row" data-drill="${esc(x.id)}"><i class="circle" style="background:${esc(x.color)}"></i><span>${esc(x.name)}<small>${pct(x.value/total*100)} от суммы</small></span><b class="num">${money(x.value)}</b></button>`).join('')}</div></div>`;}
function trend(){const ms=months(),data=ms.map(m=>chartRows(...bounds(m))),templates=chartMetric==='expenses'?Object.entries(state.categories).map(([id,x])=>({id,...x})):chartMetric==='capital'?state.participants.map(x=>({id:x.id,name:x.name,color:x.color})):chartRows(...bounds());const series=templates.map(t=>({...t,values:data.map(rows=>rows.find(x=>x.id===t.id)?.value||0)})).filter(x=>x.values.some(v=>v!==0));if(!series.length)return'<div class="empty-chart">Нет данных для динамики за эти месяцы.</div>';const flat=series.flatMap(x=>x.values),max=Math.max(100000, ...flat),min=Math.min(0,...flat),span=max-min||1,top=25,bottom=225;const y=v=>bottom-(v-min)/span*190;const base=y(0);let svg='';for(let i=0;i<5;i++){const value=min+span*i/4,yy=y(value);svg+=`<line x1="60" x2="720" y1="${yy}" y2="${yy}" stroke="#e9edf1"/><text x="50" y="${yy+4}" text-anchor="end">${Math.round(value/100000)}</text>`;}svg+=`<line x1="60" x2="720" y1="${base}" y2="${base}" stroke="#aeb9c8"/>`;const x=i=>110+i*112;for(let si=0;si<series.length;si++){const s=series[si];if(chartType==='line'){svg+=`<polyline points="${s.values.map((v,i)=>x(i)+','+y(v)).join(' ')}" fill="none" stroke="${esc(s.color)}" stroke-width="3" stroke-linejoin="round"/>`;s.values.forEach((v,i)=>svg+=`<circle cx="${x(i)}" cy="${y(v)}" r="4" fill="${esc(s.color)}" stroke="#fff" stroke-width="1.5"><title>${esc(s.name)} · ${monthName(ms[i])}: ${money(v)}</title></circle>`);}else{const width=Math.min(23,78/series.length);s.values.forEach((v,i)=>{const xx=x(i)-series.length*width/2+si*width;svg+=`<rect x="${xx}" y="${Math.min(y(v),base)}" width="${Math.max(3,width-3)}" height="${Math.max(0.5,Math.abs(base-y(v)))}" rx="2" fill="${v<0?'#b6273c':esc(s.color)}"><title>${esc(s.name)} · ${monthName(ms[i])}: ${money(v)}</title></rect>`;});}}
ms.forEach((m,i)=>svg+=`<text x="${x(i)}" y="249" text-anchor="middle">${monthShort(m)}${m===state.asOf.slice(0,7)?'*':''}</text>`);return`<div class="chart-key">${series.map(s=>`<span><i style="background:${esc(s.color)}"></i>${esc(s.name)}</span>`).join('')}</div><svg class="chart" viewBox="0 0 750 270" role="img" aria-label="Динамика за шесть месяцев. Точные значения в таблице ниже"><text x="8" y="14">тыс. ₽</text>${svg}</svg><details><summary>Таблица значений · * неполный месяц</summary><div class="tablewrap"><table class="table"><thead><tr><th>Месяц</th>${series.map(s=>`<th>${esc(s.name)}</th>`).join('')}</tr></thead><tbody>${ms.map((m,i)=>`<tr><td>${monthName(m)}</td>${series.map(s=>`<td class="right">${money(s.values[i])}</td>`).join('')}</tr>`).join('')}</tbody></table></div></details>`;}
function charts(){return`<section class="panel"><div class="graph-head"><div><h2>${chartMetric==='expenses'?'Из чего складываются расходы':chartMetric==='capital'?'Кто вложил в проект':'Динамика бизнеса'}</h2><p class="hint">${chartType==='donut'?'Структура за выбранный период · нажмите на категорию':'Последние шесть месяцев до выбранного · данные по дате признания'}</p></div><div class="graph-controls">${helpBtn('fin_chart')}<label><span class="sr-only">Показатель графика</span><select id="fin-chartMetric" class="select"><option value="expenses" ${chartMetric==='expenses'?'selected':''}>Расходы</option><option value="result" ${chartMetric==='result'?'selected':''}>Продажи и результат</option><option value="capital" ${chartMetric==='capital'?'selected':''}>Вложения</option></select></label><div class="chart-tabs">${[['donut','Круговая'],['line','Линии'],['bar','Столбцы']].map(([id,label])=>`<button data-chart="${id}" class="${chartType===id?'active':''}" aria-pressed="${chartType===id}">${label}</button>`).join('')}</div></div></div>${chartType==='donut'?donut():trend()}<div class="chart-summary"><span>${chartMetric==='expenses'?'Товар входит в расходы после приёмки заказчиком.':chartMetric==='capital'?'Только взносы в капитал. Займы и возмещения учтены отдельно.':'Результат может быть отрицательным; он не равен остатку денег.'}</span><b>${chartType==='donut'?(period==='all'?'За всё время':monthName(period)):(monthName(months()[0])+' — '+monthName(currentMonth()))}</b></div></section>`;}
function overview(){const r=report();return head('Сколько остаётся от сделок','От продажи заказчику до денег, которые остаются после закупки и работы сервиса.')+`<div class="kpis">${kpi('Продажи заказчикам',r.revenue,'Принятые поставки за период','income')}${kpi('Закупка + исполнение',r.cogs+r.direct,'Товар, доставка и расходы сделок','cost')}${kpi('Сервисы и общие расходы',r.overhead,'Подписки, разработка, содержание','service-kpi')}${kpi('Осталось до налогов',r.result,'Результат бизнеса за период','result')}</div><div class="money-bridge">${[['Продажи',r.revenue],['Себестоимость товара',r.cogs],['Расходы сделок',r.direct],['Сервисы и работа',r.overhead],['Результат',r.result]].map(([t,v],i)=>`${i?`<span class="bridge-symbol">${i===4?'=':'−'}</span>`:''}<div class="bridge-step"><span>${t}</span><b class="num ${i===4?(v<0?'bad':'good'):''}">${money(v)}</b></div>`).join('')}</div>${charts()}<div class="twocol"><section class="panel"><div class="panelhead"><h2>Где сейчас деньги ${helpBtn('fin_cash')}</h2><span class="tag">На ${shortDate(r.to)}</span></div><div class="statrow"><span>На счетах проекта</span><b>${money(r.cash)}</b></div><div class="statrow"><span>Заказчики ещё не оплатили</span><b class="copper">${money(r.receivable)}</b></div><div class="statrow"><span>Товар до приёмки заказчиком</span><b>${money(r.stock)}</b></div><p class="hint">Неоплаченная поставка уже может приносить прибыль, но деньги ещё не доступны на счёте.</p><button class="btn link" data-page="deals">Открыть сделки ${icon('arrow',14)}</button></section><section class="panel"><div class="panelhead"><h2>Контроль расходов</h2><button class="btn link" data-page="budgets">Бюджеты</button></div>${state.budgets.filter(b=>!b.deleted&&b.month===currentMonth()).slice(0,3).map(b=>{const fact=F.budgetActual(state,b);return`<div class="expenseitem"><div class="expense-top"><span>${esc(state.categories[b.category].name)}</span><b class="${fact>b.amount?'bad':'good'}">${money(fact)} / ${money(b.amount)}</b></div><div class="budgetbar"><span style="width:${b.amount?Math.min(100,fact/b.amount*100):100}%;background:${fact>b.amount?'#e34d60':'#2878ed'}"></span></div></div>`;}).join('')||'<p class="hint">На этот месяц бюджет не задан.</p>'}<button class="btn soft" data-new="budgets">Добавить бюджет</button></section></div>`;}
function selectedOps(){const [from,to]=bounds();let ids=null;if(drill?.type==='expenses')ids=new Set(F.ledger(state).filter(l=>l.date>=from&&l.date<=to&&['cogs','direct','overhead'].includes(l.debit)&&l.category===drill.id).map(l=>l.opId));return state.operations.filter(o=>Boolean(o.deleted)===showDeleted&&(ids?ids.has(o.id):o.date>=from&&o.date<=to)&&(!drill||drill.type!=='capital'||o.kind==='capital'&&o.partnerId===drill.id)&&(kindFilter==='all'||o.kind===kindFilter)&&[o.description,lookup('deals',o.dealId)?.name,pname(o.partnerId),lookup('services',o.serviceId)?.name].join(' ').toLowerCase().includes(search.toLowerCase())).sort((a,b)=>b.date.localeCompare(a.date)||b.order-a.order);}
function sliceAmount(o){if(drill?.type!=='expenses')return o.amount;const [from,to]=bounds();return F.ledger(state).filter(l=>l.opId===o.id&&l.date>=from&&l.date<=to&&l.category===drill.id&&['cogs','direct','overhead'].includes(l.debit)).reduce((s,l)=>s+l.amount,0);}
function opRows(){const items=selectedOps();return items.length?items.map(o=>`<tr class="${o.deleted?'deleted-row':''}"><td>${shortDate(o.date)}</td><td class="desc"><strong>${esc(o.description)}</strong><small>${esc(lookup('deals',o.dealId)?.name||lookup('services',o.serviceId)?.name||state.categories[o.category].name)}</small></td><td>${F.kinds[o.kind]}<small>${o.kind==='acceptance'?'Без движения денег':o.payer==='partner'?'Личная оплата: '+esc(pname(o.partnerId)):esc(lookup('accounts',o.accountId)?.name||'Без движения денег')}${o.kind==='acceptance'?' · выручка и себестоимость':''}</small></td><td class="right num">${money(sliceAmount(o))}</td><td class="row-actions">${actionButtons('operations',o)}</td></tr>`).join(''):'<tr><td colspan="5" class="empty">Операций не найдено. Измените поиск или добавьте запись.</td></tr>';}
function operations(){return head('Операции по счетам','Фактические суммы вводятся вручную. Редактирование и удаление пересчитывают весь учёт.')+`<div class="operations-top"><label><span class="sr-only">Поиск операций</span><input id="fin-search" class="search" placeholder="Найти операцию или сделку" value="${esc(search)}"></label><label><span class="sr-only">Тип операции</span><select id="fin-kindFilter" class="select"><option value="all">Все операции</option>${Object.entries(F.kinds).map(([k,v])=>`<option value="${k}" ${kindFilter===k?'selected':''}>${v}</option>`).join('')}</select></label>${helpBtn('fin_search')}<button class="btn" data-export="csv">Выгрузить CSV</button>${archivedToggle()}</div>${drill?`<div class="info">Срез: ${esc(drill.type==='expenses'?state.categories[drill.id]?.name:pname(drill.id))}. ${drill.type==='expenses'?'Сумма показывает признанный расход в этом периоде.':''} <button class="btn link" id="fin-clearDrill">Сбросить срез</button></div>`:''}<section class="panel" style="padding:0"><div class="tablewrap"><table class="table"><thead><tr><th>Дата</th><th>Операция</th><th>Вид / источник</th><th class="right">${drill?.type==='expenses'?'Расход в срезе':'Сумма операции'}</th><th class="right">Действия</th></tr></thead><tbody id="fin-operationRows">${opRows()}</tbody></table></div></section><p class="hint">Удалённые записи можно восстановить. Если изменение нарушает связанную приёмку или возврат долга, сервис покажет причину и сохранит прежние данные.</p>`;}
function deals(){const items=visibleItems('deals'),to=bounds()[1];const stage={plan:'План',won:'Выигран',delivered:'Поставка',lost:'Не выигран'};return head('Тендерные сделки','Закупка → приёмка → оплата. Прибыль возникает от поставок заказчикам.','deals','Добавить сделку')+`<div class="toolbar"><p class="hint">План не попадает в доход. Факт создаётся кнопками операций по сделке. ${helpBtn('fin_deal_ops')}</p>${archivedToggle()}</div><section class="panel" style="padding:0"><div class="tablewrap"><table class="table"><thead><tr><th>Сделка</th><th>Продажа / закупка</th><th>Результат сделки</th><th>Оплата заказчика</th><th>Действия</th></tr></thead><tbody>${items.map(d=>{const v=F.dealSummary(state,d.id,to);return`<tr><td class="desc"><strong>${esc(d.name)}</strong><small>${esc(d.customer)} · ${esc(pname(d.owner))}</small>${d.tenderNumber?`<small>Закупка № ${esc(d.tenderNumber)}</small>`:''}<small><span class="dealstage ${d.stage}">${stage[d.stage]}</span></small></td><td class="num">${money(v.accepted?v.revenue:d.planSale)}<small>${v.accepted?'Факт продажи':'План продажи'}</small><small>Куплено: ${money(v.purchase)}</small></td><td class="num ${v.accepted?(v.result<0?'bad':'good'):''}">${money(v.accepted?v.result:v.planResult)}<small>${v.accepted?'После прямых расходов':'Ожидаемый, не доход'}</small></td><td class="num">${money(v.received)}<small>${v.receivable?'К оплате: '+money(v.receivable):v.accepted?'Оплачено полностью':'До приёмки — аванс'}</small></td><td class="row-actions">${actionButtons('deals',d)}${!d.deleted?`<div class="service-tools"><button class="mini" data-deal-op="purchase" data-id="${d.id}">Закупка</button><button class="mini" data-deal-op="acceptance" data-id="${d.id}">Приёмка</button><button class="mini" data-deal-op="receipt" data-id="${d.id}">Оплата</button></div>`:''}</td></tr>`;}).join('')||'<tr><td colspan="5" class="empty">Добавьте первую сделку.</td></tr>'}</tbody></table></div></section><div class="info">Факт в таблице — накопленный по сделке на ${shortDate(to)}. Общие сервисы вычитаются один раз в сводке бизнеса. Товар следующей поставки остаётся вложением в товар до приёмки.</div>`;}
function services(){const items=visibleItems('services'),[from,to]=bounds();return head('Подписки и серверы','Добавляйте сервисы, меняйте план и записывайте каждый платёж с его фактической суммой.','services','Добавить подписку')+`<div class="toolbar"><p class="hint">Изменение плана не меняет прошлые платежи.</p>${archivedToggle('Показать удалённые подписки')}</div><div class="services">${items.map(s=>{const ops=state.operations.filter(o=>!o.deleted&&o.kind==='service'&&o.serviceId===s.id&&o.date>=from&&o.date<=to),paid=ops.reduce((n,o)=>n+o.amount,0);return`<article class="service"><div class="service-top"><div class="serviceicon" style="color:${state.categories[s.category].color}">${icon('services',22)}</div><div><h2>${esc(s.name)}</h2><p>${esc(state.categories[s.category].name)} · ${s.critical?'критичный сервис':'рабочий инструмент'}</p></div></div><div class="service-fact"><div>План ${s.cycle==='year'?'на год':s.cycle==='usage'?'потребления':'на месяц'}<strong class="num">${money(s.plan)}</strong></div><div>Оплачено за период<strong class="num ${paid?'good':''}">${money(paid)}</strong></div></div><div class="statrow"><span>Следующая дата по плану</span><b>${shortDate(s.next)}</b></div><div class="statrow"><span>Ответственный</span><b>${esc(pname(s.owner))}</b></div><div class="service-tools">${!s.deleted?`<button class="btn primary" data-service-pay="${s.id}">Записать оплату</button>`:''}${actionButtons('services',s)}</div></article>`;}).join('')||'<div class="empty">Подписок нет. Добавьте сервер, домен или рабочий инструмент.</div>'}</div><p class="hint space">Оплата здесь — запись об уже совершённом платеже, деньги сервис не списывает. При удалении подписки история её оплат сохраняется.</p>${usagePanel()}`;}
function partners(){const r=report();return head('Участники и вложения','Имена, роли, вложения и взаиморасчёты. Состав команды можно менять.','participants','Добавить участника')+`<div class="toolbar"><p class="hint">Остатки на ${shortDate(r.to)}. Вложения не определяют доли владения автоматически. ${helpBtn('fin_partner_ops')}</p>${archivedToggle('Показать участников в архиве')}</div><div class="services">${visibleItems('participants').map(p=>{const v=r.partners.find(x=>x.id===p.id);return`<article class="partnercard"><div class="partnerheader"><span class="avatar" style="background:${esc(p.color)};color:white">${esc(p.name.slice(0,1))}</span><div><h2>${esc(p.name)}</h2><p>${esc(p.role||'Участник')} ${p.deleted?'· архив':''}</p></div></div><div class="hint">Вложено в капитал</div><div class="partnerbig num">${money(v.capital)}</div><div class="statrow"><span>Остаток займа</span><b>${money(v.loan)}</b></div><div class="statrow"><span>Личные оплаты к возмещению</span><b>${money(v.payable)}</b></div><div class="statrow"><span>Выплачено участнику</span><b>${money(v.distributed)}</b></div><div class="partner-tools">${actionButtons('participants',p)}${!p.deleted?`<button class="mini" data-partner-op="capital" data-id="${p.id}">Внести деньги</button><button class="mini" data-partner-op="reimburse" data-id="${p.id}">Возместить</button><button class="mini" data-partner-op="withdraw" data-id="${p.id}">Выплата</button>`:''}</div></article>`;}).join('')||'<p class="empty">Нет участников в этом списке.</p>'}</div><div class="info">Удаление участника означает архивирование: его вклады, долги и история сохраняются. Переименование обновляется во всех связанных записях.</div>`;}
function scenarioResult(){const margin=Math.round(scenario.sale*100)-Math.round(scenario.purchase*100)-Math.round(scenario.direct*100),result=margin*scenario.count-Math.round(scenario.services*100);return`<div class="eyebrow" style="color:#b7d3ff">План сделок · не факт</div><div class="hint">Остаток после сервисов до налогов</div><div class="value num">${money(result)}</div><div class="cashrow"><span>Одна сделка после прямых расходов</span><b>${money(margin)}</b></div><div class="cashfoot">${margin>0?`Для покрытия ${money(Math.round(scenario.services*100))} сервисов нужно минимум <b>${Math.ceil(Math.round(scenario.services*100)/margin)} таких сделок</b>.`:'При этих ценах сделка не покрывает собственные расходы.'}<br>Это сценарий одинаковых сделок; сроки оплаты и оборотный капитал считаются отдельно.</div>`;}
function budgets(){const m=currentMonth();return head('Бюджеты и план','Контролируйте траты по статьям и участникам, планируйте прибыль от перепродажи.','budgets','Добавить бюджет')+`<div class="toolbar"><p class="hint">Бюджеты на ${monthName(m)}. Общий лимит и лимиты участников не складываются.</p>${archivedToggle()}</div><div class="budgetcards">${visibleItems('budgets').filter(b=>b.month===m).map(b=>{const fact=F.budgetActual(state,b),over=fact>b.amount;return`<article class="budgetcard"><div class="panelhead"><div><h2>${esc(state.categories[b.category].name)}</h2><p>${b.owner?'Ответственный: '+esc(pname(b.owner)):'Весь проект'}</p></div><span class="pill ${over?'warn':''}">${over?'Лимит превышен':'В пределах'}</span></div><div class="budgetnumbers"><span>Факт<br><strong class="${over?'bad':'good'}">${money(fact)}</strong></span><span>Бюджет<br><strong>${money(b.amount)}</strong></span></div><div class="budgetbar"><span style="width:${b.amount?Math.min(100,fact/b.amount*100):fact?100:0}%;background:${over?'#e34d60':'#2878ed'}"></span></div><p class="hint">${over?'Сверх бюджета: '+money(fact-b.amount):'Осталось: '+money(b.amount-fact)}</p><div class="service-tools">${actionButtons('budgets',b)}</div></article>`;}).join('')||'<p class="empty">На этот месяц бюджет не задан.</p>'}</div><section class="panel" style="margin-top:22px"><div class="panelhead"><div><h2>План прибыли от тендеров ${helpBtn('fin_scenario')}</h2><p>Все суммы можно изменить. Расчёт не создаёт реальные операции.</p></div></div><div class="twocol"><form id="fin-scenarioForm"><div class="fields">${[['sale','Продажа одной сделки, ₽'],['purchase','Закупка товара, ₽'],['direct','Расходы одной сделки, ₽'],['count','Количество сделок'],['services','Сервисы и общие расходы, ₽']].map(([k,label])=>`<div class="field ${k==='services'?'full':''}"><label for="scenario-${k}">${label}</label><input id="scenario-${k}" name="${k}" type="number" min="0" max="${k==='count'?1000:100000000}" step="${k==='count'?'1':'0.01'}" value="${scenario[k]}" required></div>`).join('')}</div></form><div class="scenarioresult" id="fin-scenarioResult" aria-live="polite">${scenarioResult()}</div></div></section>`;}
function accounts(){const r=report();return head('Счета и остатки','Добавляйте счета проекта и переводите деньги между ними без изменения прибыли.','accounts','Добавить счёт')+`<div class="toolbar"><p class="hint">Остатки на ${shortDate(r.to)}. Новый счёт создаётся с нулём. ${helpBtn('fin_transfer')}</p>${archivedToggle()}</div><div class="accountcards">${visibleItems('accounts').map(a=>{const balance=r.accounts.find(x=>x.id===a.id).balance;return`<article class="accountcard"><h2>${esc(a.name)}</h2><div class="value num ${balance<0?'bad':''}">${money(balance)}</div><div class="service-tools">${actionButtons('accounts',a)}${!a.deleted?`<button class="mini" data-transfer="${a.id}">Перевести между счетами</button>`:''}</div></article>`;}).join('')}</div><div class="info" style="margin-top:20px">Сумма по счетам: <b>${money(r.cash)}</b>. Перевод внутри проекта не создаёт выручку или расход. Комиссию записывайте отдельным общим расходом.</div>`;}
function settings(){return head('Настройки проекта','Название, резервы и данные. Всё хранится на сервере вместе с закупками.',null)+`<section class="panel"><div class="settingrow"><div><h2>Название платформы</h2><span>${esc(state.settings.name)}</span></div><button class="btn" data-new="settings">Изменить</button></div><div class="settingrow"><div><h2>Резерв на развитие ${helpBtn('fin_reserves')}</h2><span>${money(state.settings.reserve)} · уменьшает ориентир свободных денег, не прибыль</span></div><button class="btn" data-new="settings">Изменить</button></div><div class="settingrow"><div><h2>Резерв на налоги</h2><span>${state.settings.taxReserve?money(state.settings.taxReserve):'Не задан'} · вводится вручную, не заменяет налоговый расчёт</span></div><button class="btn" data-new="settings">Изменить</button></div></section><section class="panel"><h2>Ваши данные ${helpBtn('fin_data')}</h2><p class="hint">Данные общие для всех, кто входит в сервис. Загрузка файла из демо заменяет текущие записи; прежние остаются в архиве.</p><div class="actions"><button class="btn" data-export="json">Скачать JSON-копию</button><button class="btn" data-export="all">Скачать все операции в CSV</button><button class="btn" id="fin-importBackup">Загрузить JSON</button></div></section><section class="panel"><h2>История изменений ${helpBtn('fin_audit')}</h2><p class="hint">Всего изменений: ${state.audit.length}. Удалённые записи доступны через переключатель в своём разделе.</p><div class="tablewrap"><table class="table"><thead><tr><th>Время</th><th>Раздел</th><th>Действие</th></tr></thead><tbody>${[...state.audit].reverse().slice(0,12).map(a=>`<tr><td>${esc(new Date(a.at).toLocaleString('ru-RU',{timeZone:'Europe/Moscow'}))}</td><td>${esc(({operations:'Операции',services:'Подписки',participants:'Участники',accounts:'Счета',deals:'Сделки',budgets:'Бюджеты',settings:'Настройки'})[a.collection]||a.collection)}</td><td>${({save:'Сохранено',delete:'Удалено / архив',restore:'Восстановлено'})[a.action]||esc(a.action)}</td></tr>`).join('')||'<tr><td colspan="3" class="empty">Изменений пока нет.</td></tr>'}</tbody></table></div></section>`;}
function context(){const r=report(),due=state.services.filter(s=>!s.deleted&&s.next>=state.asOf&&s.next<=F.addMonth(state.asOf,1)).sort((a,b)=>a.next.localeCompare(b.next));return`<section class="cashcard"><div class="eyebrow">На счетах · ${shortDate(r.to)}</div><div class="cashamount num ${r.cash<0?'bad':''}">${money(r.cash)}</div><div class="cashrow"><span>Возместить участникам</span><b>${money(r.payable)}</b></div><div class="cashrow"><span>Остаток займов</span><b>${money(r.loans)}</b></div><div class="cashrow"><span>Авансы заказчиков</span><b>${money(r.advances)}</b></div><div class="cashrow"><span>Резервы проекта и налогов</span><b>${money(state.settings.reserve+state.settings.taxReserve)}</b></div><div class="balance-summary"><span class="hint" style="color:#d6d9cf">После долгов и выбранных резервов</span><b class="num">${money(r.indicativeFree)}</b></div><div class="cashfoot">Ориентир по текущим настройкам. Будущие закупки не вычтены. ${!state.settings.taxReserve?'Налоговый резерв не задан.':''}</div></section><section class="contextsection"><div class="panelhead"><h2>Ближайшие оплаты ${helpBtn('fin_due')}</h2><span class="tag">От ${shortDate(state.asOf)}</span></div>${due.slice(0,3).map(s=>`<div class="due"><div class="datebox"><strong>${Number(s.next.slice(-2))}</strong><small>${monthShort(s.next.slice(0,7))}</small></div><div class="duebody"><b>${esc(s.name)}</b><span>${money(s.plan)} · план</span></div></div>`).join('')||'<p class="note">Платежей по плану нет.</p>'}<button class="btn link" data-page="services">Все подписки ${icon('arrow',14)}</button></section><section class="contextsection"><h2>Что важно видеть</h2>${r.accounts.some(a=>a.balance<0)?'<div class="attention">На одном из счетов отрицательный остаток. Проверьте ввод и финансирование.</div>':''}<div class="attention">${r.receivable?`Заказчики должны ${money(r.receivable)}. Прибыль уже учтена, деньги ещё не получены.`:'Неоплаченных принятых поставок на эту дату нет.'}</div><p class="note">Результат месяца и остаток денег отвечают на разные вопросы. Вклад партнёра увеличивает деньги, а не прибыль.</p></section>`;}
function usagePanel(){const rows=meta.usage||[];if(!rows.length)return'';return`<section class="panel"><div class="panelhead"><div><h2>Платные запросы сервиса ${helpBtn('fin_usage')}</h2><p>Справка: сколько запросов сделал сервис. Операции из этого не создаются.</p></div></div><div class="tablewrap"><table class="table"><thead><tr><th>Источник</th><th class="right">Сегодня</th><th class="right">За месяц</th></tr></thead><tbody>${rows.map(u=>`<tr><td>${esc(u.name)}</td><td class="right num">${u.today}</td><td class="right num">${u.month}</td></tr>`).join('')}</tbody></table></div></section>`;}
function startScreen(){return`<section class="panel fin-start"><h1>Финансов пока нет ${helpBtn('fin_start')}</h1><p class="subtitle">Начните с нуля или загрузите файл, сохранённый в демо (JSON версии 2). Учебные данные демо в рабочую базу не попадают.</p><div class="actions"><button class="btn primary" id="fin-start">Начать с нуля</button><button class="btn" id="fin-importBackup">Загрузить JSON</button></div></section>`;}
function render(){if(!root||!state)return;$('#fin-nav').innerHTML=Object.entries(names).map(([id,label])=>`<button class="navitem ${page===id?'active':''}" data-page="${id}" ${page===id?'aria-current="page"':''}>${icon(id)}${label}</button>`).join('');const ctx=$('#fin-context');if(meta.empty){$('#fin-main').innerHTML=startScreen();ctx.hidden=true;return;}ctx.hidden=false;const pages={overview,deals,operations,services,partners,budgets,accounts,settings};$('#fin-main').innerHTML=pages[page]()+`<div class="footerline">Налоги автоматически не рассчитываются.</div>`;ctx.innerHTML=context();}
const SHELL=`<div class="fin"><nav id="fin-nav" class="finnav" aria-label="Разделы финансов"></nav><div class="main-layout"><div class="fin-main" id="fin-main" tabindex="-1"></div><aside class="context" id="fin-context" aria-label="Деньги и обязательства"></aside></div><dialog id="fin-editor" aria-labelledby="fin-editorTitle"><form id="fin-editorForm"><div class="dialoghead"><h2 id="fin-editorTitle"></h2><button class="close" type="button" data-close aria-label="Закрыть">×</button></div><div class="info" id="fin-editorHint"></div><div class="fields" id="fin-editorFields"></div><p class="formerror" id="fin-editorError" role="alert"></p><div class="actions"><button class="btn primary" type="submit">Сохранить</button><button class="btn" type="button" data-close>Отмена</button></div></form></dialog><dialog id="fin-confirm" aria-labelledby="fin-confirmTitle"><div class="dialoghead"><h2 id="fin-confirmTitle">Подтвердите действие</h2><button class="close" type="button" data-close aria-label="Закрыть">×</button></div><p class="subtitle" id="fin-confirmText"></p><p class="formerror" id="fin-confirmError" role="alert"></p><div class="actions"><button class="btn danger" id="fin-confirmAction">Удалить</button><button class="btn" type="button" data-close>Отмена</button></div></dialog><input type="file" id="fin-backupFile" accept="application/json,.json" class="hidden"><div id="fin-toast" class="toast hidden" role="status"></div></div>`;
/** Открыть раздел: данные каждый раз с сервера — партнёр мог что-то изменить. */
async function open(el){if(root!==el){root=el;root.innerHTML=SHELL;root.addEventListener('click',onClick);root.addEventListener('change',onChange);root.addEventListener('input',onInput);$('#fin-editorForm').addEventListener('submit',submitEditor);$('#fin-backupFile').addEventListener('change',onFile);}try{const j=await api('/api/finance');state=j.state;meta=j.meta;if(!period)period=state.asOf.slice(0,7);render();}catch(error){$('#fin-main').innerHTML='<div class="empty">'+esc(error.message)+'</div>';}}
window.FinanceTab={open};

const collectionLabels={operations:'операцию',services:'подписку',participants:'участника',accounts:'счёт',deals:'сделку',budgets:'бюджет',settings:'настройки'};
function field(name,label,value='',type='text',extra=''){return `<div class="field" data-field="${name}"><label for="f-${name}">${label}</label><input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${extra}></div>`;}
function select(name,label,items,value,optional=false){return `<div class="field" data-field="${name}"><label for="f-${name}">${label}</label><select id="f-${name}" name="${name}" ${optional?'':'required'}>${optional?'<option value="">Весь проект / не назначен</option>':''}${items.map(([id,title])=>`<option value="${esc(id)}" ${id===value?'selected':''}>${esc(title)}</option>`).join('')}</select></div>`;}
function options(g,id){return state[g].filter(x=>!x.deleted||x.id===id).map(x=>[x.id,x.name+(x.deleted?' · архив':'')]);}
const monetary=(name,label,n=0)=>field(name,label,(n/100).toFixed(2),'text','inputmode="decimal" required maxlength="16"');
const categories=()=>Object.entries(state.categories).map(([id,x])=>[id,x.name]);
function openEditor(collection,id=null,preset={}){
 const existing=id?lookup(collection,id):null;
 const v={...(existing||{}),...preset};editing={collection,id,existing};
 $('#fin-editorTitle').textContent=(id?'Изменить ':'Добавить ')+collectionLabels[collection];
 $('#fin-editorError').textContent='';let html='',hint='';
 if(collection==='operations'){
  v.kind=v.kind||'overhead';v.date=v.date||state.asOf;v.accountId=v.accountId||state.accounts.find(x=>!x.deleted)?.id;
  v.owner=v.owner||state.participants.find(x=>!x.deleted)?.id;v.category=v.category||'other';
  html=select('kind','Вид операции',Object.entries(F.kinds),v.kind)+monetary('amount','Фактическая сумма, ₽',v.amount)+field('date','Дата',v.date,'date',`required max="${state.asOf}"`)+field('description','Описание',v.description||'','text','required maxlength="180"')+
   select('dealId','Тендерная сделка',options('deals',v.dealId),v.dealId)+select('serviceId','Подписка / сервис',options('services',v.serviceId),v.serviceId)+
   select('payer','Кто оплатил',[['project','Со счёта проекта'],['partner','Участник личными деньгами']],v.payer||'project')+
   select('accountId','Счёт проекта',options('accounts',v.accountId),v.accountId)+select('toAccountId','Счёт назначения',options('accounts',v.toAccountId),v.toAccountId)+
   select('partnerId','Участник: внёс / оплатил / получил',options('participants',v.partnerId),v.partnerId)+select('owner','Ответственный',options('participants',v.owner),v.owner,true)+
   select('category','Статья расходов',categories(),v.category)+field('months','Признать расход за месяцев',v.months||1,'number','min="1" max="60" step="1" required')+field('document','Номер подтверждающего документа',v.document||'','text','maxlength="120"');
  hint='Записывается уже совершённая операция. План подписки не меняется от фактической оплаты. Приёмка признаёт продажу и списывает товар; деньги приходят отдельной операцией.';
 }else if(collection==='services'){
  html=field('name','Название подписки',v.name||'','text','required maxlength="120"')+select('category','Статья расходов',categories(),v.category||'ai')+monetary('plan','Плановая сумма за период, ₽',v.plan)+select('cycle','Период',[['month','Месяц'],['year','Год'],['usage','По потреблению']],v.cycle||'month')+field('next','Дата следующей оплаты',v.next||F.addMonth(state.asOf,1),'date','required')+select('owner','Ответственный',options('participants',v.owner),v.owner,true)+`<div class="field full"><label class="checkboxline"><input name="critical" type="checkbox" ${v.critical?'checked':''}> Критичный для работы сервис</label></div>`;
  hint='План используется для напоминаний. Сумму каждой реальной оплаты вы вводите отдельно — она может меняться каждый месяц.';
 }else if(collection==='participants'){
  html=field('name','Имя участника',v.name||'','text','required maxlength="120"')+field('role','Роль',v.role||'','text','maxlength="120"')+field('color','Цвет на графиках',v.color||'#2878ed','color');hint='Имя можно менять без потери истории. Вложения, займы и личные оплаты учитываются раздельно.';
 }else if(collection==='accounts'){
  html=field('name','Название счёта',v.name||'','text','required maxlength="120"');hint='Счёт создаётся с нулевым остатком. Внесённые деньги добавьте операцией с правильным источником.';
 }else if(collection==='deals'){
  html=field('name','Название сделки',v.name||'','text','required maxlength="120"')+field('customer','Заказчик',v.customer||'','text','required maxlength="180"')+select('stage','Этап',[['plan','План'],['won','Выигран'],['delivered','Поставка'],['lost','Не выигран']],v.stage||'plan')+select('owner','Ответственный',options('participants',v.owner),v.owner,true)+field('tenderNumber','Номер закупки (если есть)',v.tenderNumber||'','text','maxlength="64"')+monetary('planSale','План продажи, ₽',v.planSale)+monetary('planBuy','План закупки, ₽',v.planBuy)+monetary('planDirect','План прямых расходов, ₽',v.planDirect);
  hint='Плановые суммы не создают доход или расход. Для факта добавьте закупку, приёмку и оплату заказчика. На сделку одна приёмка.';
 }else if(collection==='budgets'){
  html=field('month','Месяц',v.month||currentMonth(),'month','required')+select('category','Статья',categories(),v.category||'ai')+monetary('amount','Бюджет, ₽',v.amount)+select('owner','Ответственный / весь проект',options('participants',v.owner),v.owner,true);hint='Факт — признанные расходы по статье и ответственному. Общий бюджет и вложенные лимиты участников не суммируются.';
 }else if(collection==='settings'){
  $('#fin-editorTitle').textContent='Настройки проекта';const s=state.settings;html=field('name','Название платформы',s.name,'text','required maxlength="80"')+monetary('reserve','Резерв на развитие, ₽',s.reserve)+monetary('taxReserve','Резерв на налоги, ₽',s.taxReserve);hint='Резервы уменьшают ориентир свободных денег. Они не создают расходы и не заменяют расчёт налогов.';
 }
 $('#fin-editorFields').innerHTML=html;$('#fin-editorHint').textContent=hint;
 if(collection==='operations')syncOperationFields(!existing);
 $('#fin-editor').showModal();
}
function syncOperationFields(updateCategory=false){
 const form=$('#fin-editorForm'),v={kind:form.elements.kind.value,payer:form.elements.payer.value},kind=v.kind;
 const payable=['purchase','direct','service','overhead'].includes(kind),personal=payable&&v.payer==='partner';
 const participant=['capital','loan','loan_repay','reimburse','withdraw'].includes(kind);
 const show={dealId:['purchase','acceptance','receipt','direct'].includes(kind),serviceId:kind==='service',payer:payable,accountId:kind!=='acceptance'&&!personal,toAccountId:kind==='transfer',partnerId:participant||personal,owner:kind!=='transfer',category:['direct','service','overhead'].includes(kind),months:kind==='service'};
 for(const [name,visible] of Object.entries(show)){const wrapper=$(`[data-field="${name}"]`);wrapper.hidden=!visible;wrapper.querySelectorAll('input,select').forEach(el=>el.disabled=!visible);}
 if(updateCategory&&kind==='service'){const s=lookup('services',$('#f-serviceId').value);if(s)$('#f-category').value=s.category;}
 if(updateCategory&&kind==='direct')$('#f-category').value='logistics';
 $('[data-field="amount"] label').textContent=kind==='acceptance'?'Принятая стоимость продажи, ₽':'Фактическая сумма, ₽';
}
async function submitEditor(e){
 e.preventDefault();const {collection,id,existing}=editing;const values=Object.fromEntries(new FormData(e.target)),v=values;let patch;
 try{
  if(collection==='operations'){
   const kind=v.kind,payable=['purchase','direct','service','overhead'].includes(kind),hasPartner=['capital','loan','loan_repay','reimburse','withdraw'].includes(kind)||payable&&v.payer==='partner';
   patch={kind,amount:F.minor(v.amount),date:v.date,description:v.description.trim(),order:existing?.order??Math.max(0,...state.operations.map(o=>o.order||0))+1,deleted:false,accountId:kind==='acceptance'||payable&&v.payer==='partner'?null:v.accountId,payer:payable?v.payer:'project',partnerId:hasPartner?v.partnerId:null,owner:kind==='transfer'?null:v.owner||null,toAccountId:kind==='transfer'?v.toAccountId:null,dealId:['purchase','acceptance','receipt','direct'].includes(kind)?v.dealId:null,serviceId:kind==='service'?v.serviceId:null,months:kind==='service'?Number(v.months):1,category:kind==='purchase'||kind==='acceptance'?'goods':v.category||'other',document:v.document||''};
  }else if(collection==='services')patch={name:v.name.trim(),category:v.category,plan:F.minor(v.plan,true),cycle:v.cycle,next:v.next,owner:v.owner||null,critical:v.critical==='on',deleted:false};
  else if(collection==='participants')patch={name:v.name.trim(),role:v.role.trim(),color:v.color,deleted:false};
  else if(collection==='accounts')patch={name:v.name.trim(),deleted:false};
  else if(collection==='deals')patch={name:v.name.trim(),customer:v.customer.trim(),stage:v.stage,owner:v.owner||null,planSale:F.minor(v.planSale,true),planBuy:F.minor(v.planBuy,true),planDirect:F.minor(v.planDirect,true),tenderNumber:v.tenderNumber.trim(),deleted:false};
  else if(collection==='budgets')patch={month:v.month,category:v.category,amount:F.minor(v.amount,true),owner:v.owner||null,deleted:false};
  if(collection==='settings'){
   apply(await api('/api/finance/settings',{name:v.name.trim(),reserve:F.minor(v.reserve,true),taxReserve:F.minor(v.taxReserve,true)}),'Настройки сохранены');
  }else await change(collection,id||uid(),patch,'save','Сохранено. Отчёты пересчитаны');
  $('#fin-editor').close();editing=null;
 }catch(error){$('#fin-editorError').textContent=error.message;}
}
function askConfirm(title,message,label,action){$('#fin-confirmTitle').textContent=title;$('#fin-confirmText').textContent=message;$('#fin-confirmAction').textContent=label;$('#fin-confirmError').textContent='';confirmAction=action;$('#fin-confirm').showModal();}
function navigate(id){if(!names[id])return;page=id;showDeleted=false;render();$('#fin-main').focus({preventScroll:true});}
function download(name,content,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportData(type){if(type==='json'){location.href='/api/finance/export.json';return;}if(type==='all'){location.href='/api/finance/export.csv';return;}const rows=[['Дата','Описание','Вид','Сумма, руб.','Сумма в срезе, руб.','Сделка','Сервис','Ответственный','Участник','Удалено'],...selectedOps().map(o=>[o.date,o.description,F.kinds[o.kind],(o.amount/100).toFixed(2),(sliceAmount(o)/100).toFixed(2),lookup('deals',o.dealId)?.name||'',lookup('services',o.serviceId)?.name||'',pname(o.owner),o.partnerId?pname(o.partnerId):'',o.deleted?'Да':'Нет'])];download('tender-ai-operations-'+period+'.csv','\uFEFF'+rows.map(row=>row.map(F.csvCell).join(';')).join('\r\n'),'text/csv;charset=utf-8');toast('CSV содержит текущий отфильтрованный список');}

async function onClick(e){
 const b=e.target.closest('button');if(!b)return;
 try{
  if(b.hasAttribute('data-close')){b.closest('dialog').close();return;}
  if(b.dataset.page){drill=null;navigate(b.dataset.page);return;}
  if(b.dataset.month){period=b.dataset.month;render();return;}
  if(b.dataset.new){openEditor(b.dataset.new);return;}
  if(b.dataset.edit){openEditor(b.dataset.edit,b.dataset.id);return;}
  if(b.dataset.delete){const collection=b.dataset.delete,id=b.dataset.id,item=lookup(collection,id);askConfirm('Удалить '+collectionLabels[collection]+'?',`«${item.name||item.description||monthName(item.month)}». ${collection==='operations'?'Отчёты пересчитаются. Связанные обязательства будут проверены.':'Запись будет архивирована, история останется.'} Запись можно восстановить.`, 'Удалить',()=>change(collection,id,null,'delete','Запись удалена / перенесена в архив'));return;}
  if(b.dataset.restore){await change(b.dataset.restore,b.dataset.id,null,'restore','Запись восстановлена');return;}
  if(b.dataset.chart){chartType=b.dataset.chart;if(chartType==='donut'&&chartMetric==='result'){chartMetric='expenses';toast('Круговая показывает структуру расходов. Для прибыли с убытками используйте линии или столбцы.');}render();return;}
  if(b.dataset.drill){drill={type:chartMetric,id:b.dataset.drill};kindFilter='all';search='';navigate('operations');return;}
  if(b.dataset.servicePay){const s=lookup('services',b.dataset.servicePay);openEditor('operations',null,{kind:'service',serviceId:s.id,category:s.category,owner:s.owner,amount:s.plan,description:s.name+' · оплата'});return;}
  if(b.dataset.partnerOp){const id=b.dataset.id;openEditor('operations',null,{kind:b.dataset.partnerOp,partnerId:id,owner:id,description:F.kinds[b.dataset.partnerOp]+': '+pname(id)});return;}
  if(b.dataset.dealOp){const d=lookup('deals',b.dataset.id),v=F.dealSummary(state,d.id),kind=b.dataset.dealOp;openEditor('operations',null,{kind,dealId:d.id,owner:d.owner,amount:kind==='purchase'?d.planBuy:kind==='acceptance'?d.planSale:v.receivable||d.planSale,description:F.kinds[kind]+': '+d.name});return;}
  if(b.dataset.transfer){openEditor('operations',null,{kind:'transfer',accountId:b.dataset.transfer,toAccountId:state.accounts.find(a=>!a.deleted&&a.id!==b.dataset.transfer)?.id,description:'Перевод между счетами проекта'});return;}
  if(b.dataset.export){exportData(b.dataset.export);return;}
  if(b.id==='fin-clearDrill'){drill=null;render();return;}
  if(b.id==='fin-start'){apply(await api('/api/finance/start',{}),'Можно начинать: добавьте участников и счёт');return;}if(b.id==='fin-confirmAction'){try{await confirmAction();$('#fin-confirm').close();confirmAction=null;}catch(error){$('#fin-confirmError').textContent=error.message;}return;}
  if(b.id==='fin-importBackup'){$('#fin-backupFile').click();return;}
 }catch(error){toast(error.message);}
}
function onChange(e){
 const t=e.target;
 if(t.id==='fin-period'){period=t.value;render();}
 if(t.id==='fin-chartMetric'){chartMetric=t.value;if(chartMetric==='result'&&chartType==='donut'){chartType='line';toast('Результат с возможными убытками показан линиями.');}render();}
 if(t.id==='fin-kindFilter'){kindFilter=t.value;$('#fin-operationRows').innerHTML=opRows();}
 if(t.id==='fin-showDeleted'){showDeleted=t.checked;render();}
 if(['f-kind','f-payer','f-serviceId'].includes(t.id)&&editing?.collection==='operations')syncOperationFields(t.id!=='f-payer');
}
function onInput(e){
 if(e.target.id==='fin-search'){search=e.target.value;$('#fin-operationRows').innerHTML=opRows();}
 if(e.target.closest('#scenarioForm')){const form=$('#fin-scenarioForm');if(!form.checkValidity()){$('#fin-scenarioResult').textContent='Проверьте суммы и целое количество сделок.';return;}scenario=Object.fromEntries([...new FormData(form)].map(([k,v])=>[k,Number(v)]));$('#fin-scenarioResult').innerHTML=scenarioResult();}
}
async function onFile(e){const f=e.target.files[0];if(!f)return;try{if(f.size>2*1024*1024)throw Error('Размер файла — не больше 2 МБ');const next=JSON.parse(await f.text());F.ledger(next);askConfirm('Восстановить JSON-копию?',`Текущие данные будут заменены. Проект: ${next.settings.name}, операций: ${next.operations.length}.`,'Восстановить',async()=>{drill=null;apply(await api('/api/finance/import',{state:next}),'Данные загружены');period=state.asOf.slice(0,7);render();});}catch(error){toast('Не удалось прочитать файл: '+error.message);}e.target.value='';}

})();
